package com.certmanage.notification;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.dao.DuplicateKeyException;
import com.certmanage.smtp.SmtpService;
import java.util.*;
import java.time.*;
import static com.certmanage.common.Errors.require;
@Service
public class NotificationService {
 private final com.certmanage.common.ExecutionLog logs;private final JdbcTemplate db;private final SmtpService smtp;public NotificationService(JdbcTemplate d,SmtpService s,com.certmanage.common.ExecutionLog logs){db=d;smtp=s;this.logs=logs;}
 public Map<String,Object> get(){var r=db.queryForMap("select * from notification_policy where id=1");return Map.of("enabled",r.get("ENABLED"),"timezone",r.get("TIMEZONE_ID"),"scanTime",r.get("SCAN_TIME").toString(),"warningDays",r.get("WARNING_DAYS"),"includeCa",r.get("INCLUDE_CA"),"thresholds",db.queryForList("select threshold_days from notification_thresholds order by threshold_days desc",Integer.class),"recipients",db.queryForList("select email_address from notification_recipients order by id",String.class));}
 @Transactional public void save(Map<String,Object>b,long actor){String zone=Objects.toString(b.get("timezone"),"Asia/Shanghai"),time=Objects.toString(b.get("scanTime"),"09:00");try{ZoneId.of(zone);LocalTime.parse(time);}catch(Exception e){throw new IllegalArgumentException("时区或检查时间不合法");}int warning=((Number)b.getOrDefault("warningDays",30)).intValue();require(warning>=0&&warning<=3650,"预警天数超出范围");@SuppressWarnings("unchecked") List<Number>thresholds=(List<Number>)b.getOrDefault("thresholds",List.of(30,14,7,1));@SuppressWarnings("unchecked") List<String>recipients=(List<String>)b.getOrDefault("recipients",List.of());require(!thresholds.isEmpty()&&thresholds.size()<=20,"请配置1-20个提醒节点");for(var t:thresholds)require(t.intValue()>=0&&t.intValue()<=3650,"提醒天数超出范围");for(String email:recipients)require(SmtpService.validEmail(email.trim()),"收件邮箱不合法");boolean enabled=Boolean.TRUE.equals(b.get("enabled"));if(enabled){require(!recipients.isEmpty(),"启用前请填写收件人");require(db.queryForObject("select count(*) from smtp_config",Integer.class)>0,"启用前请配置SMTP");}db.update("update notification_policy set enabled=?,timezone_id=?,scan_time=?,warning_days=?,include_ca=?,updated_by=?,config_revision=config_revision+1,updated_at=current_timestamp where id=1",enabled,zone,LocalTime.parse(time),warning,Boolean.TRUE.equals(b.get("includeCa")),actor);db.update("delete from notification_thresholds");for(int days:thresholds.stream().mapToInt(Number::intValue).distinct().toArray())db.update("insert into notification_thresholds values(1,?)",days);db.update("delete from notification_recipients");var seen=new HashSet<String>();for(String email:recipients){String clean=email.trim(),key=emailKey(clean);if(seen.add(key))db.update("insert into notification_recipients(policy_id,email_address,email_key) values(1,?,?)",clean,key);}}
 public static String emailKey(String email){int at=email.lastIndexOf('@');return email.substring(0,at)+email.substring(at).toLowerCase(Locale.ROOT);}
 public synchronized int scan(){logs.append("NOTIFICATION","SCAN_STARTED","STARTED","notification-worker",null,null,"POLICY",1L,"到期通知扫描开始",Map.of());int count;try{count=scanPolicy();}catch(RuntimeException e){logs.append("NOTIFICATION","SCAN_FAILURE","FAILURE","notification-worker",null,null,"POLICY",1L,"通知扫描失败",Map.of());throw e;}logs.append("NOTIFICATION","SCAN_SUCCESS","SUCCESS","notification-worker",null,null,"POLICY",1L,"到期通知扫描完成",Map.of("count",count));return count;}
 private int scanPolicy(){var p=get();if(!Boolean.TRUE.equals(p.get("enabled")))return 0;ZoneId zone=ZoneId.of((String)p.get("timezone"));var now=ZonedDateTime.now(zone);if(now.toLocalTime().isBefore(LocalTime.parse((String)p.get("scanTime"))))return 0;@SuppressWarnings("unchecked") List<Integer>thresholds=(List<Integer>)p.get("thresholds");var recipients=db.queryForList("select * from notification_recipients");String filter=Boolean.TRUE.equals(p.get("includeCa"))?"":" and a.certificate_kind='LEAF'";var certs=db.queryForList("select a.id,a.purpose,m.common_name,m.not_after,c.customer_name from certificate_assets a join certificate_materials m on m.id=a.material_id left join customers c on c.id=a.customer_id where a.deleted_at is null and m.not_after>current_timestamp"+filter);int created=0;for(var c:certs){var expiry=((OffsetDateTime)c.get("NOT_AFTER")).atZoneSameInstant(zone);long days=java.time.temporal.ChronoUnit.DAYS.between(now.toLocalDate(),expiry.toLocalDate());if(!thresholds.contains((int)days))continue;for(var r:recipients){try{db.update("insert into notification_deliveries(asset_id,policy_id,threshold_days,recipient_address,recipient_key,not_after_snapshot,cn_snapshot,customer_snapshot,purpose_snapshot,message_id) values(?,1,?,?,?,?,?,?,?,?)",c.get("ID"),days,r.get("EMAIL_ADDRESS"),r.get("EMAIL_KEY"),c.get("NOT_AFTER"),c.get("COMMON_NAME"),c.get("CUSTOMER_NAME"),c.get("PURPOSE"),"<"+UUID.randomUUID()+"@certmanage.local>");created++;}catch(DuplicateKeyException ignored){}}}return created;}
 @Scheduled(fixedDelay=60000,initialDelay=60000) public void tick(){try{scan();sendPending();}catch(Exception e){logs.append("NOTIFICATION","WORKER_FAILURE","FAILURE","notification-worker",null,null,null,null,"通知后台任务异常",Map.of());org.slf4j.LoggerFactory.getLogger(getClass()).warn("通知任务暂未完成，检查数据库及配置");}}
 public synchronized void sendPending(){for(long stale:db.queryForList("select id from notification_deliveries where delivery_status='SENDING' and lease_until<current_timestamp",Long.class))logs.append("NOTIFICATION","DELIVERY_INTERRUPTED","INTERRUPTED","notification-worker",null,null,"DELIVERY",stale,"通知投递租约过期，上次结果不确定",Map.of());db.update("update notification_attempts set outcome='UNKNOWN',finished_at=current_timestamp where outcome='STARTED' and delivery_id in(select id from notification_deliveries where delivery_status='SENDING' and lease_until<current_timestamp)");db.update("update notification_deliveries set delivery_status='RETRY_WAIT',next_attempt_at=current_timestamp,lease_owner=null where delivery_status='SENDING' and lease_until<current_timestamp");var jobs=db.queryForList("select d.*,a.owner_type from notification_deliveries d join certificate_assets a on a.id=d.asset_id where a.deleted_at is null and delivery_status in('PENDING','RETRY_WAIT') and (next_attempt_at is null or next_attempt_at<=current_timestamp) order by d.id fetch first 20 rows only");for(var j:jobs){long id=((Number)j.get("ID")).longValue();int attempt=((Number)j.get("ATTEMPTS")).intValue()+1;String lease=UUID.randomUUID().toString();int claimed=db.update("update notification_deliveries set delivery_status='SENDING',attempts=?,lease_owner=?,lease_until=dateadd('MINUTE',5,current_timestamp) where id=? and delivery_status in('PENDING','RETRY_WAIT')",attempt,lease,id);if(claimed==0)continue;boolean accepted=false;db.update("insert into notification_attempts(delivery_id,attempt_no,started_at,outcome) values(?,?,current_timestamp,'STARTED')",id,attempt);try{logs.append("NOTIFICATION","DELIVERY_STARTED","STARTED","notification-worker",null,null,"DELIVERY",id,"通知投递开始",Map.of("attempt",attempt));smtp.send(j.get("RECIPIENT_ADDRESS").toString(),"证书到期提醒："+j.get("CN_SNAPSHOT"),mailBody(j,Instant.now(),ZoneId.of((String)get().get("timezone"))),j.get("MESSAGE_ID").toString());accepted=true;db.update("update notification_deliveries set delivery_status='SENT',sent_at=current_timestamp,error_message=null,lease_until=null where id=? and lease_owner=?",id,lease);db.update("update notification_attempts set outcome='SUCCESS',finished_at=current_timestamp where delivery_id=? and attempt_no=?",id,attempt);logs.appendAfterEffect("NOTIFICATION","DELIVERY_SUCCESS","SUCCESS","notification-worker",null,null,"DELIVERY",id,"通知投递成功",Map.of("attempt",attempt));}catch(Exception e){if(accepted){db.update("update notification_deliveries set delivery_status='SENT',sent_at=coalesce(sent_at,current_timestamp),error_message=null,lease_until=null where id=? and lease_owner=?",id,lease);db.update("update notification_attempts set outcome='SUCCESS',finished_at=current_timestamp where delivery_id=? and attempt_no=?",id,attempt);logs.appendAfterEffect("NOTIFICATION","DELIVERY_SUCCESS","SUCCESS","notification-worker",null,null,"DELIVERY",id,"邮件已确认接受，已恢复成功结果",Map.of("attempt",attempt));continue;}db.update("update notification_deliveries set delivery_status=?,next_attempt_at=dateadd('MINUTE',15,current_timestamp),error_message='SMTP发送失败，请检查连接、TLS及凭据',lease_until=null where id=? and lease_owner=?",attempt>=3?"FAILED":"RETRY_WAIT",id,lease);db.update("update notification_attempts set outcome='FAILURE',finished_at=current_timestamp,error_message='SMTP发送失败' where delivery_id=? and attempt_no=?",id,attempt);logs.append("NOTIFICATION","DELIVERY_FAILURE","FAILURE","notification-worker",null,null,"DELIVERY",id,"通知投递失败",Map.of("attempt",attempt));}}}
 public static String mailBody(Map<String,Object> job,Instant now,ZoneId zone){var expiry=(OffsetDateTime)job.get("NOT_AFTER_SNAPSHOT");long days=java.time.temporal.ChronoUnit.DAYS.between(now.atZone(zone).toLocalDate(),expiry.atZoneSameInstant(zone).toLocalDate());return "证书："+job.get("CN_SNAPSHOT")+"\n归属："+("OWN".equals(job.get("OWNER_TYPE"))?"自有证书":"客户证书")+"\n用途："+job.get("PURPOSE_SNAPSHOT")+"\n客户："+Objects.toString(job.get("CUSTOMER_SNAPSHOT"),"—")+"\n到期时间："+expiry.atZoneSameInstant(zone)+"\n剩余天数："+days+"\n提醒节点：提前"+job.get("THRESHOLD_DAYS")+"天";}
 public List<Map<String,Object>> records(){return db.queryForList("select id,cn_snapshot,recipient_address,threshold_days,delivery_status,attempts,error_message,created_at,sent_at from notification_deliveries order by id desc fetch first 200 rows only");}
 public void retry(long id){require(db.update("update notification_deliveries set delivery_status='RETRY_WAIT',attempts=attempts,next_attempt_at=current_timestamp where id=? and delivery_status='FAILED' and asset_id in(select id from certificate_assets where deleted_at is null)",id)==1,"只能重试失败任务");logs.append("NOTIFICATION","RETRY_QUEUED","INFO","notification-worker",null,null,"DELIVERY",id,"通知已重新入队",Map.of());}
}

